<script lang="ts">
  import{onMount}from'svelte';import{api}from'../lib/api';import{t}from'../../shared/i18n.svelte';type Trace={enabled:boolean;path:string;filter:string;max_string_chars:number};type Config={server?:{stream_trace?:Partial<Trace>}};const defaults:Trace={enabled:false,path:'',filter:'',max_string_chars:20000};let draft=$state<Trace>({...defaults});let baseline=$state('');let loading=$state(true);let saving=$state(false);let error=$state('');let notice=$state('');const message=(value:unknown)=>value instanceof Error?value.message:String(value);const normalize=(trace:Partial<Trace>={}):Trace=>({enabled:!!trace.enabled,path:String(trace.path??'').trim(),filter:String(trace.filter??'').trim(),max_string_chars:Number.isFinite(Number(trace.max_string_chars))&&Number(trace.max_string_chars)>0?Number(trace.max_string_chars):20000});async function load(signal?:AbortSignal){try{const config=await api.get<Config>('/admin/api/config',signal);draft=normalize(config.server?.stream_trace);baseline=JSON.stringify(draft);error='';}catch(cause){if(!(cause instanceof DOMException&&cause.name==='AbortError'))error=message(cause);}finally{loading=false;}}async function save(){saving=true;error='';notice='';try{const result=await api.put<{server?:{stream_trace?:Partial<Trace>}}>('/admin/api/config/server',{stream_trace:normalize(draft)});draft=normalize(result.server?.stream_trace??draft);baseline=JSON.stringify(draft);notice=t('toast.gatewayLogsSaved');}catch(cause){error=message(cause);}finally{saving=false;}}onMount(()=>{const controller=new AbortController();void load(controller.signal);return()=>controller.abort();});
</script>
<div class="section"><div class="section-header"><h2>{t('section.gatewayLogs')}</h2><button class="btn btn-primary btn-sm" disabled={loading||saving||baseline===JSON.stringify(normalize(draft))} onclick={()=>void save()}>{t('btn.save')}</button></div>{#if error}<div class="toast error show" role="alert">{error}</div>{/if}{#if notice}<div class="toast show" role="status">{notice}</div>{/if}<div class="provider-card" style="max-width:720px"><div class="form-group"><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" disabled={loading} checked={draft.enabled} onclick={()=>{draft.enabled=!draft.enabled;}} style="width:auto" /><span>{t('label.streamTraceEnabled')}</span></label><div style="font-size:11px;color:var(--text-dim);margin-top:6px">{t('label.streamTraceHint')}</div></div><div class="form-group"><label for="streamTracePath">{t('label.streamTracePath')}</label><input id="streamTracePath" disabled={loading} bind:value={draft.path} style="font-family:var(--mono)" placeholder={t('placeholder.streamTracePath')} spellcheck="false" /><div style="font-size:11px;color:var(--text-dim);margin-top:6px">{t('label.streamTracePathHint')}</div></div><div class="form-group"><label for="streamTraceFilter">{t('label.streamTraceFilter')}</label><input id="streamTraceFilter" disabled={loading} bind:value={draft.filter} placeholder={t('placeholder.streamTraceFilter')} /><div style="font-size:11px;color:var(--text-dim);margin-top:6px">{t('label.streamTraceFilterHint')}</div></div><div class="form-group" style="margin-bottom:0"><label for="streamTraceMaxChars">{t('label.streamTraceMaxChars')}</label><input id="streamTraceMaxChars" disabled={loading} type="number" min="1" step="1000" bind:value={draft.max_string_chars} placeholder="20000" style="max-width:180px" /></div></div></div>
